const fs = require('fs');
const path = require('path');

function getFiles(dir) {
  let results = [];
  if (!fs.existsSync(dir)) return results;
  const list = fs.readdirSync(dir);
  list.forEach(file => {
    const fullPath = path.join(dir, file);
    const stat = fs.statSync(fullPath);
    if (stat && stat.isDirectory()) {
      results = results.concat(getFiles(fullPath));
    } else {
      results.push(fullPath);
    }
  });
  return results;
}

const componentFiles = getFiles('site/components').map(f => f.replace(/\\/g, '/'));
const focssFiles = getFiles('site/focss').map(f => f.replace(/\\/g, '/'));

console.log(`Analyzing ${componentFiles.length} component files and ${focssFiles.length} FOCSS files...`);

const stats = {
  totalComponents: componentFiles.length,
  byExtension: {},
  subdirectories: {},
  useClientCount: 0,
  serverComponentCount: 0,
  anyUsage: [],
  boundaryViolations: [],
  largeComponents: [],
  propInterfaces: 0,
  noPropInterface: [],
  inlineStylesCount: 0,
  filesWithInlineStyles: [],
  focssImports: 0,
  tailwindClassUsage: 0
};

for (const file of componentFiles) {
  const ext = path.extname(file);
  stats.byExtension[ext] = (stats.byExtension[ext] || 0) + 1;

  const relDir = path.relative('site/components', path.dirname(file)).replace(/\\/g, '/') || 'root';
  stats.subdirectories[relDir] = (stats.subdirectories[relDir] || 0) + 1;

  const content = fs.readFileSync(file, 'utf8');
  const lines = content.split('\n');

  if (lines.length > 300) {
    stats.largeComponents.push({ file, lines: lines.length });
  }

  const isClient = /['"]use client['"]/.test(content);
  if (isClient) {
    stats.useClientCount++;
  } else if (ext === '.tsx' || ext === '.jsx') {
    stats.serverComponentCount++;
  }

  // Check boundary violations
  if (file.includes('/Studio/') && (content.includes('/Planner') || content.includes('Planner/'))) {
    stats.boundaryViolations.push({ file, target: 'Planner' });
  }
  if (file.includes('/Planner/') && (content.includes('/Studio') || content.includes('Studio/'))) {
    stats.boundaryViolations.push({ file, target: 'Studio' });
  }

  // Check 'any' usage
  const anyMatches = content.match(/:\s*any\b|as\s+any\b|<any>/g);
  if (anyMatches && (ext === '.tsx' || ext === '.ts')) {
    stats.anyUsage.push({ file, count: anyMatches.length });
  }

  // Check prop interface / type
  if (ext === '.tsx') {
    if (/interface\s+\w+Props|type\s+\w+Props\s*=|\(\s*\{\s*[^}]+\}\s*:\s*\{/.test(content)) {
      stats.propInterfaces++;
    } else {
      stats.noPropInterface.push(file);
    }
  }

  // Check inline styles
  if (/style=\{\{/.test(content)) {
    stats.inlineStylesCount++;
    stats.filesWithInlineStyles.push(file);
  }

  if (/@focss|focss/.test(content)) {
    stats.focssImports++;
  }

  if (/className=/.test(content)) {
    stats.tailwindClassUsage++;
  }
}

console.log('--- ANALYSIS SUMMARY ---');
console.log('Total Components:', stats.totalComponents);
console.log('By Extension:', stats.byExtension);
console.log('Use Client vs Server:', { client: stats.useClientCount, server: stats.serverComponentCount });
console.log('Boundary Violations (Studio <-> Planner):', stats.boundaryViolations.length);
console.log('Components with `any`:', stats.anyUsage.length, stats.anyUsage);
console.log('Large Components (>300 lines):', stats.largeComponents.length);
console.log('Inline style usage count:', stats.inlineStylesCount);
console.log('FOCSS imports count:', stats.focssImports);
console.log('Subdirectories breakdown:', stats.subdirectories);

