const fs = require('fs');
const path = require('path');

function getFiles(dir) {
  let results = [];
  if (!fs.existsSync(dir)) return results;
  const list = fs.readdirSync(dir);
  list.forEach(file => {
    const fullPath = path.join(dir, file);
    const stat = fs.statSync(fullPath);
    if (stat && stat.isDirectory()) {
      results = results.concat(getFiles(fullPath));
    } else {
      results.push(fullPath);
    }
  });
  return results;
}

const componentFiles = getFiles('site/components').map(f => f.replace(/\\/g, '/'));

const analysisByDir = {};

componentFiles.forEach(file => {
  const rel = path.relative('site/components', file).replace(/\\/g, '/');
  const dir = path.dirname(rel);
  if (!analysisByDir[dir]) analysisByDir[dir] = [];

  const content = fs.readFileSync(file, 'utf8');
  const lines = content.split('\n').length;
  const isClient = /['"]use client['"]/.test(content);
  const usesFocss = /@focss|focss/.test(content);
  const usesTailwind = /className=/.test(content);
