  const hasInlineStyle = /style=\{\{/.test(content);

  analysisByDir[dir].push({
    fileName: path.basename(file),
    relPath: rel,
    lines,
    isClient,
    usesFocss,
    usesTailwind,
    hasAria,
    hasInlineStyle
  });
});

console.log('Categories count:', Object.keys(analysisByDir).length);
for (const [dir, files] of Object.entries(analysisByDir)) {
  console.log(`- ${dir || '.'}: ${files.length} files, avg lines: ${Math.round(files.reduce((a,b)=>a+b.lines,0)/files.length)}`);
}

