const fs = require('fs');
const path = require('path');

function getFiles(dir) {
  let results = [];
  if (!fs.existsSync(dir)) return results;
  const list = fs.readdirSync(dir);
  list.forEach(file => {
    const fullPath = path.join(dir, file);
    try {
      const stat = fs.statSync(fullPath);
      if (stat && stat.isDirectory()) {
        results = results.concat(getFiles(fullPath));
      } else {
        results.push(fullPath);
      }
    } catch (e) {}
  });
  return results;
}

const ompFiles = getFiles('.omp').map(f => f.replace(/\\/g, '/'));
console.log(`Total files in .omp/: ${ompFiles.length}\n`);

const summary = {};
ompFiles.forEach(f => {
  const parts = f.split('/');
  const category = parts.length > 2 ? parts.slice(0, 3).join('/') : parts.slice(0, 2).join('/');
  if (!summary[category]) summary[category] = [];
  const stat = fs.statSync(f);
  summary[category].push({ file: f, size: stat.size });
});

for (const [cat, files] of Object.entries(summary)) {
  console.log(`Category: ${cat} (${files.length} files, total ${(files.reduce((a,b)=>a+b.size,0)/1024).toFixed(1)} KB)`);
  files.slice(0, 5).forEach(f => {
    console.log(`  - ${path.basename(f.file)} (${(f.size/1024).toFixed(1)} KB)`);
  });
  if (files.length > 5) console.log(`  ... and ${files.length - 5} more files`);
  console.log('');
}

